<template>
  <div v-if="visible && (value || isNew)" class="value-edit-form">
    <q-card flat bordered class="form-card">
      <q-card-section class="form-header">
        <div class="row items-center">
          <div class="text-subtitle1 text-weight-medium">
            {{ isNew ? $t('create_values') : $t('edit_value') }}
          </div>
          <q-space />
          <q-btn
            flat
            dense
            round
            icon="close"
            size="sm"
            @click="handleCancel"
            :aria-label="$t('close')"
          />
        </div>
      </q-card-section>

      <q-separator />

      <q-card-section class="form-body">
        <div class="row q-col-gutter-sm">
          <!-- Value field -->
          <div class="col-12 col-md-6">
            <q-input
              v-model="formData.value"
              :label="$t('value')"
              outlined
              dense
              ref="firstFieldRef"
              :rules="[(val) => !!val || $t('field_required')]"
              :readonly="isDefaultValue || (!isNew && value !== null && value.label && value.label.length > 0)"
            />
          </div>

          <!-- Sub-Organization field -->
          <div class="col-12 col-md-6">
            <q-select
              v-model="formData.sub_org_id"
              :options="subOrgOptions"
              :label="$t('sub_organization')"
              outlined
              dense
              emit-value
              map-options
              clearable
              :readonly="isDefaultValue"
              :disable="isDefaultValue"
            />
          </div>

          <!-- Synonyms field -->
          <div class="col-12">
            <q-select
              v-model="formData.synonyms"
              :label="$t('synonyms')"
              outlined
              dense
              multiple
              use-chips
              use-input
              new-value-mode="add-unique"
              :hint="$t('press_enter_to_add')"
              :readonly="isSynonymReadonly"
            >
              <template v-slot:selected-item="scope">
                <q-chip
                  removable
                  @remove="scope.removeAtIndex(scope.index)"
                  :tabindex="scope.tabindex"
                  color="primary"
                  text-color="white"
                  class="q-ma-xs"
                >
                  {{ scope.opt }}
                </q-chip>
              </template>
            </q-select>
          </div>

          <!-- Translations -->
          <div class="col-12">
            <div class="text-caption text-weight-medium q-mb-xs">
              {{ $t('translations') }}
            </div>
            <div
              v-for="(label, idx) in formData.labels"
              :key="idx + '-' + (label.language || '') + '-' + (label.org_id || '')"
              class="row q-col-gutter-xs items-center q-mb-xs"
            >
              <div class="col-4">
                <q-select
                  v-model="label.language"
                  :options="languageOptions"
                  :label="$t('language')"
                  outlined
                  dense
                  emit-value
                  map-options
                  class="compact-field"
                  :readonly="isDefaultOrg(label.org_id)"
                  :disable="isDefaultOrg(label.org_id)"
                />
              </div>
              <div class="col-7">
                <q-input
                  v-model="label.translated_value"
                  :label="$t('label')"
                  outlined
                  dense
                  class="compact-field"
                  :readonly="isDefaultOrg(label.org_id)"
                />
              </div>
              <div class="col-1 flex items-center justify-center">
                <q-btn
                  v-if="formData.labels.length > 1 && !isDefaultOrg(label.org_id)"
                  flat
                  dense
                  round
                  icon="delete"
                  color="negative"
                  size="xs"
                  @click="removeLabel(idx)"
                />
              </div>
            </div>
            <q-btn
              flat
              dense
              icon="add"
              :label="$t('add_translation')"
              color="primary"
              size="xs"
              class="q-mt-xs"
              @click="addLabel"
            />
          </div>
        </div>
      </q-card-section>

      <q-separator />

      <q-card-actions class="form-actions">
        <div class="row full-width items-center">
          <q-space />

          <!-- Primary actions -->
          <div class="col-auto">
            <q-btn
              flat dense
              :label="$t('cancel')"
              color="grey-7"
              @click="handleCancel"
              class="q-mr-sm"
            />
            <q-btn
              unelevated dense
              :label="isNew ? $t('save') : $t('save_changes')"
              color="primary"
              @click="handleSave"
              :loading="saving"
            />
          </div>
        </div>
      </q-card-actions>
    </q-card>
  </div>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { useDropdownStore } from 'src/store/main';
import { defineComponent, type PropType } from 'vue';
import { DEFAULT_LANGUAGE, isDefaultOrg } from 'src/constants';
import { getOrgId } from 'src/utils/organization/org_id_helper';
import type { ListValue, ValueLabel, ValueFormData } from '../types';

function createEmptyLabel(orgId: string): ValueLabel {
  return { language: DEFAULT_LANGUAGE, translated_value: '', org_id: orgId };
}

export default defineComponent({
  name: 'ValueEditForm',

  props: {
    value: {
      type: Object as PropType<ListValue | null>,
      default: null,
    },
    visible: {
      type: Boolean,
      default: false,
    },
    isNew: {
      type: Boolean,
      default: false,
    },
    listName: {
      type: String,
      default: '',
    },
    selectedListOrgId: {
      type: String,
      default: '',
    },
  },

  emits: ['save', 'cancel'],

  setup() {
    const dropdownStore = useDropdownStore();
    const { subOrgList } = storeToRefs(dropdownStore);
    const { getSubOrgsList } = dropdownStore;
    return { subOrgList, getSubOrgsList };
  },

  data() {
    return {
      saving: false,
      isAddingTranslation: false,
      formData: {
        value: '',
        sub_org_id: undefined,
        synonyms: [],
        labels: [createEmptyLabel('')],
      } as ValueFormData,
    };
  },

  computed: {
    subOrgOptions(): { label: string; value: string }[] {
      return this.subOrgList.map((org: any) => ({
        label: org.label,
        value: org.value,
      }));
    },

    languageOptions(): { label: string; value: string }[] {
      return [
        { label: this.$t('english'), value: DEFAULT_LANGUAGE },
        { label: this.$t('german'), value: 'de' },
        { label: this.$t('french'), value: 'fr' },
        { label: this.$t('spanish'), value: 'es-es' },
        { label: this.$t('italian'), value: 'it' },
        { label: this.$t('dutch'), value: 'nl' },
        { label: this.$t('chinese'), value: 'zh' },
      ];
    },

    isDefaultValue(): boolean {
      if (!this.value || this.isNew) return false;
      return isDefaultOrg(this.value.org_id);
    },

    isSynonymReadonly(): boolean {
      return this.isDefaultValue;
    },

    availableLanguageOptions(): { label: string; value: string }[] {
      const used = this.formData.labels.map((l) => l.language);
      return this.languageOptions.filter((lang) => !used.includes(lang.value));
    },
  },

  watch: {
    value: {
      handler(newValue: ListValue | null) {
        if (this.isAddingTranslation) return;
        if (!newValue) return;

        this.formData = {
          value: newValue.value,
          sub_org_id: newValue.sub_org_id,
          synonyms: [...newValue.synonyms],
          labels:
            newValue.label && newValue.label.length > 0
              ? newValue.label.map((l) => ({ ...l }))
              : [createEmptyLabel(this.selectedListOrgId)],
        };
      },
      immediate: true,
      deep: true,
    },

    isNew(val: boolean) {
      if (val && !this.value) {
        this.resetFormForNew();
      }
    },

    async visible(isVisible: boolean) {
      if (isVisible) {
        await this.$nextTick();
        (this.$refs.firstFieldRef as any)?.focus();
      }
    },
  },

  mounted() {
    this.getSubOrgsList();
  },

  methods: {
    isDefaultOrg,

    resetFormForNew() {
      this.formData = {
        value: '',
        sub_org_id: undefined,
        synonyms: [],
        labels: [createEmptyLabel(this.selectedListOrgId)],
      };
    },

    addLabel() {
      this.isAddingTranslation = true;
      const nextLang = this.availableLanguageOptions[0];
      this.formData.labels.push({
        language: nextLang ? nextLang.value : DEFAULT_LANGUAGE,
        translated_value: '',
        org_id: getOrgId(),
      });
      this.$nextTick(() => {
        this.isAddingTranslation = false;
      });
    },

    removeLabel(index: number) {
      this.formData.labels.splice(index, 1);
    },

    handleSave() {
      this.saving = true;
      try {
        this.$emit('save', { ...this.formData });
      } finally {
        this.saving = false;
      }
    },

    handleCancel() {
      this.$emit('cancel');
    },

  },
});
</script>

