<template>
  <div class="list-navigator">
    <div class="nav-header">
      <q-input
        v-model="search"
        dense
        outlined
        :placeholder="$t('search_lists')"
      >
        <template v-slot:prepend><q-icon name="search" /></template>
      </q-input>
      <q-btn
        color="primary"
        icon="add"
        :label="$t('new')"
        class="full-width q-mt-sm"
        dense
        unelevated
        no-caps
        @click="showCreateDialog = true"
      />
    </div>
    <q-scroll-area class="nav-list">
      <!-- Loading skeleton -->
      <q-list v-if="loading">
        <q-item v-for="i in 5" :key="'skeleton-' + i">
          <q-item-section avatar>
            <q-skeleton type="QAvatar" />
          </q-item-section>
          <q-item-section>
            <q-skeleton type="text" />
          </q-item-section>
          <q-item-section side>
            <q-skeleton type="QBadge" />
          </q-item-section>
        </q-item>
      </q-list>

      <!-- Empty state when no lists and not loading -->
      <div v-else-if="!lists.length" class="empty-state">
        <q-icon name="inbox" size="64px" color="grey-5" class="q-mb-md" />
        <div class="text-subtitle1 text-grey-7 q-mb-sm">
          {{ $t('no_lists_available') }}
        </div>
        <div class="text-body2 text-grey-6 q-mb-md">
          {{ $t('create_list_or_check_connection') }}
        </div>
        <q-btn
          color="primary"
          :label="$t('retry')"
          icon="refresh"
          size="sm"
          outline
          @click="$emit('retry')"
        />
      </div>

      <!-- List items -->
      <q-list v-else class="nav-list-inner">
        <q-item
          v-for="list in filteredLists"
          :key="list.id"
          clickable
          :active="selectedListId === list.id"
          class="list-nav-item"
          @click="$emit('list-selected', list.id)"
        >
          <q-item-section avatar class="nav-item-avatar">
            <q-icon
              :name="list.is_default ? 'folder_special' : 'folder'"
              size="18px"
              color="grey-7"
            />
          </q-item-section>
          <q-item-section class="nav-item-label-section">
            <q-item-label class="nav-item-label" lines="1">
              {{ list.display_name }}
              <q-tooltip
                anchor="top middle"
                self="bottom middle"
                :delay="400"
                max-width="280px"
              >
                {{ list.display_name }}
              </q-tooltip>
            </q-item-label>
          </q-item-section>
          <q-item-section side class="nav-item-action">
            <div class="row items-center no-wrap">
              <q-spinner v-if="list.item_count === -1" size="xs" color="grey-6" />
              <q-badge v-else color="primary">{{ list.item_count }}</q-badge>
              <q-btn
                v-if="!list.is_default"
                flat
                dense
                round
                icon="more_vert"
                size="sm"
                class="q-ml-xs"
                @click.stop
              >
                <q-menu
                  auto-close
                  transition-show="jump-down"
                  transition-hide="jump-up"
                >
                  <q-list dense style="min-width: 120px">
                    <q-item clickable @click="confirmDeleteList(list)">
                      <q-item-section>
                        <span class="text-red">{{ $t('delete') }}</span>
                      </q-item-section>
                    </q-item>
                  </q-list>
                </q-menu>
              </q-btn>
            </div>
          </q-item-section>
        </q-item>
      </q-list>
    </q-scroll-area>
  </div>

  <!-- Create New List Dialog -->
  <q-dialog v-model="showCreateDialog" persistent @keydown.esc="showCreateDialog = false">
    <CreateList />
  </q-dialog>

  <!-- Delete Confirmation Dialog -->
  <q-dialog v-model="showDeleteConfirm" persistent>
    <q-card style="min-width: 400px">
      <q-card-section class="bg-primary text-white q-pa-md">
        <div class="row items-center">
          <q-icon name="warning" size="sm" color="white" class="q-mr-sm" />
          <div class="text-h6">{{ $t('warning_item_will_be_deleted') }}</div>
        </div>
      </q-card-section>

      <q-card-section class="q-pt-md">
        <p>{{ $t('delete_selected_item_msg') }}</p>
      </q-card-section>

      <q-card-actions align="right" class="q-pa-md">
        <f-btn appearance="cancel" :label="$t('cancel')" v-close-popup />
        <f-btn
          :label="$t('delete')"
          :loading="deleting"
          @click="handleDeleteList"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>
</template>

<script lang="ts">

import type { ListMetadata } from '../types';
import { defineComponent, PropType } from 'vue';
import CreateList from '../../ListOfValues/CreateList.vue';
import { useListOfValues } from '../composables/useListOfValues';

export default defineComponent({
  name: 'ListNavigator',

  components: {
    CreateList,
  },

  props: {
    lists: {
      type: Array as PropType<ListMetadata[]>,
      required: true,
    },
    selectedListId: {
      type: String as PropType<string | null>,
      default: null,
    },
    loading: {
      type: Boolean,
      default: false,
    },
  },

  emits: ['list-selected', 'retry'],

  setup() {
    const { fetchLists, deleteList } = useListOfValues();
    return { fetchLists, deleteList };
  },

  data() {
    return {
      search: '',
      showCreateDialog: false,
      showDeleteConfirm: false,
      listToDelete: null as ListMetadata | null,
      deleting: false,
    };
  },

  computed: {
    filteredLists(): ListMetadata[] {
      if (!this.search) return this.lists;
      return this.lists.filter(
        (l) =>
          l.name.toLowerCase().includes(this.search.toLowerCase()) ||
          l.display_name.toLowerCase().includes(this.search.toLowerCase()),
      );
    },
  },

  mounted() {
    document.addEventListener('row_added', this.handleRowAdded);
  },

  beforeUnmount() {
    document.removeEventListener('row_added', this.handleRowAdded);
  },

  methods: {
    handleRowAdded() {
      this.showCreateDialog = false;
      this.fetchLists();
    },

    confirmDeleteList(list: ListMetadata) {
      this.listToDelete = list;
      this.showDeleteConfirm = true;
    },

    async handleDeleteList() {
      if (!this.listToDelete) return;

      this.deleting = true;
      try {
        await this.deleteList(this.listToDelete.name);
        this.showDeleteConfirm = false;
        this.listToDelete = null;
        this.fetchLists();
      } finally {
        this.deleting = false;
      }
    },
  },
});
</script>

