/**
 * useListOfValues Composable
 * Handles all API interactions for List of Values redesign
 */

import { ref, computed } from 'vue';
import { listOfValuesApiService } from 'src/services';
import { CONSTANTS, DEFAULT_ORG_UUID } from 'src/constants';
import type {
  ListMetadata,
  ListValue,
  SortPreference,
  PaginationMeta,
} from '../types';

export function useListOfValues() {
  // State
  const lists = ref<ListMetadata[]>([]);
  const currentValues = ref<ListValue[]>([]);
  const loading = ref({
    lists: false,
    values: false,
    saving: false,
  });
  const error = ref<string | null>(null);
  const pagination = ref<PaginationMeta>({
    current_page: 1,
    total_pages: 1,
    total_items: 0,
    items_per_page: 50,
  });

  // Computed
  const hasLists = computed(() => lists.value.length > 0);
  const hasValues = computed(() => currentValues.value.length > 0);
  const isLoading = computed(
    () => loading.value.lists || loading.value.values || loading.value.saving,
  );

  /**
   * Fetch all lists with metadata
   * TODO: Update when backend implements /summary endpoint
   */
  async function fetchLists(search?: string): Promise<void> {
    try {
      loading.value.lists = true;
      error.value = null;

      // Currently using existing API - will enhance when backend is ready
      const response = await listOfValuesApiService.getLists(false);

      if (!response.success || !response.data) {
        throw new Error(response.message || 'Failed to fetch lists');
      }

      // Transform old format to new format with metadata
      const transformedLists: ListMetadata[] = [];

      for (const [list_name, listInfo] of Object.entries(response.data)) {
        const item = listInfo as any;

        // API may return value as string (old format) or array of translations (new format)
        let listName: string;
        if (typeof item.value === 'string') {
          listName = item.value;
        } else if (Array.isArray(item.value) && item.value.length > 0) {
          listName = item.value[0].translated_value || String(item.value[0]);
        } else if (item.name) {
          listName = String(item.name);
        } else if (item.label) {
          listName = String(item.label);
        } else {
          listName = String(item.value);
        }

        transformedLists.push({
          id: listName,
          name: listName,
          display_name: listName
            .split('_')
            .map((word: string) => word.charAt(0).toUpperCase() + word.slice(1))
            .join(' '),
          org_id: String(item.org_id || ''),
          is_default: item.org_id === DEFAULT_ORG_UUID,
          item_count: -1, // -1 indicates not loaded yet, 0 means empty list
          sort_preference: 'alphabetical', // Default until backend supports it
          custom_order: null,
          created_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
          created_by: 'system',
        });
      }

      // Apply search filter if provided
      if (search && search.trim()) {
        const searchLower = search.toLowerCase();
        lists.value = transformedLists.filter(
          (list) =>
            list.name.toLowerCase().includes(searchLower) ||
            list.display_name.toLowerCase().includes(searchLower),
        );
      } else {
        lists.value = transformedLists;
      }

      // Fetch counts in background (non-blocking)
      fetchAllListCounts();
    } catch (err: any) {
      error.value = err.message || 'Failed to load lists';
      console.error('Error fetching lists:', err);
    } finally {
      loading.value.lists = false;
    }
  }

  /**
   * Fetch item count for a specific list without loading all values
   * @param listId - List identifier
   * @returns Number of items in the list
   */
  async function fetchListItemCount(listId: string): Promise<number> {
    try {
      const response = await listOfValuesApiService.getValuesForList(
        listId,
        true,
      );

      if (!response.success || !response.data) {
        return 0;
      }

      return Object.keys(response.data).length;
    } catch (err) {
      console.error(`Error fetching count for list ${listId}:`, err);
      return 0;
    }
  }

  /**
   * Fetch values for a specific list
   * @param listId - List identifier
   * @param sort - Sort preference
   * @param page - Page number for pagination
   */
  async function fetchValuesForList(
    listId: string,
    sort: SortPreference = 'alphabetical',
    page = 1,
  ): Promise<void> {
    try {
      loading.value.values = true;
      error.value = null;

      // Currently using existing API
      const response = await listOfValuesApiService.getValuesForList(
        listId,
        true,
      );

      if (!response.success || !response.data) {
        throw new Error(response.message || 'Failed to fetch values');
      }

      // Transform old format to new format
      const transformedValues: ListValue[] = [];

      for (const [index, valueInfo] of Object.entries(response.data)) {
        const item = valueInfo as any;

        // API now returns value as an array of translation objects and label as the value string
        const valueStr = String(item.label || item.value);
        const labels = Array.isArray(item.value) ? item.value : (Array.isArray(item.label) ? item.label : []);

        transformedValues.push({
          id: String(item.id || index),
          value: valueStr,
          org_id: String(item.org_id || ''),
          sub_org_id: item.sub_org_id,
          synonyms: Array.isArray(item.synonyms) ? item.synonyms : [],
          label: labels,
          created_at: item.created_at || new Date().toISOString(),
          updated_at: item.updated_at || new Date().toISOString(),
          created_by: item.created_by || 'system',
          sort_index: Number(index),
        });
      }

      // Apply sorting locally until backend supports it
      currentValues.value = applySorting(transformedValues, sort);

      // Update item count in list metadata
      const listIndex = lists.value.findIndex((l) => l.id === listId);
      if (listIndex !== -1) {
        lists.value[listIndex].item_count = currentValues.value.length;
      }

      // Update pagination
      pagination.value = {
        current_page: page,
        total_pages: Math.ceil(currentValues.value.length / 50),
        total_items: currentValues.value.length,
        items_per_page: 50,
      };
    } catch (err: any) {
      error.value = err.message || 'Failed to load values';
      console.error('Error fetching values:', err);
    } finally {
      loading.value.values = false;
    }
  }

  /**
   * Fetch counts for all lists in parallel (non-blocking background operation)
   */
  async function fetchAllListCounts(): Promise<void> {
    // Fetch counts for all lists in parallel
    const countPromises = lists.value.map(async (list) => {
      const count = await fetchListItemCount(list.id);

      // Update count in place
      const listIndex = lists.value.findIndex((l) => l.id === list.id);
      if (listIndex !== -1) {
        lists.value[listIndex].item_count = count;
      }
    });

    // Wait for all counts to load (runs in background)
    try {
      await Promise.all(countPromises);
    } catch (err) {
      console.error('Error fetching list counts:', err);
    }
  }

  /**
   * Apply local sorting (temporary until backend implements server-side sorting)
   * @param values - Array of values to sort
   * @param sort - Sort preference
   */
  function applySorting(
    values: ListValue[],
    sort: SortPreference,
  ): ListValue[] {
    const sorted = [...values];

    switch (sort) {
      case 'alphabetical':
        return sorted.sort((a, b) => a.value.localeCompare(b.value));

      case 'alphabetical_desc':
        return sorted.sort((a, b) => b.value.localeCompare(a.value));

      case 'recently_modified':
        return sorted.sort(
          (a, b) =>
            new Date(b.updated_at).getTime() - new Date(a.updated_at).getTime(),
        );

      case 'custom':
        // Custom order will be handled separately
        return sorted;

      case 'backend':
      default:
        return sorted.sort((a, b) => (a.sort_index || 0) - (b.sort_index || 0));
    }
  }

  /**
   * Save custom sort order
   * TODO: Implement when backend endpoint is ready
   * @param listId - List identifier
   * @param customOrder - Array of value IDs in desired order
   */
  async function saveCustomOrder(
    listId: string,
    customOrder: string[],
  ): Promise<boolean> {
    try {
      loading.value.saving = true;
      error.value = null;

      // TODO: Replace with actual API call when endpoint is ready
      // const payload: SaveOrderRequest = {
      //   sort_preference: 'custom',
      //   custom_order: customOrder,
      //   org_id: getCurrentOrgId(),
      // };
      // const response = await api.put(`/list-of-values/${listId}/order`, payload);

      // Temporary: Store in local storage until backend is ready
      localStorage.setItem(
        `${CONSTANTS.pattern_lov_custom_order}${listId}`,
        JSON.stringify(customOrder),
      );

      // Update list metadata
      const listIndex = lists.value.findIndex((l) => l.id === listId);
      if (listIndex !== -1) {
        lists.value[listIndex].sort_preference = 'custom';
        lists.value[listIndex].custom_order = customOrder;
      }

      // Reorder current values
      const reordered = customOrder
        .map((valueId) => currentValues.value.find((v) => v.id === valueId))
        .filter((v): v is ListValue => v !== undefined);

      currentValues.value = reordered;

      return true;
    } catch (err: any) {
      error.value = err.message || 'Failed to save custom order';
      console.error('Error saving custom order:', err);
      return false;
    } finally {
      loading.value.saving = false;
    }
  }

  /**
   * Load custom order from local storage (temporary)
   * @param listId - List identifier
   */
  function loadCustomOrder(listId: string): string[] | null {
    const stored = localStorage.getItem(`${CONSTANTS.pattern_lov_custom_order}${listId}`);
    return stored ? JSON.parse(stored) : null;
  }

  /**
   * Delete a list
   * @param listName - Name of the list to delete
   */
  async function deleteList(listName: string): Promise<boolean> {
    try {
      loading.value.saving = true;
      error.value = null;

      const response = await listOfValuesApiService.deleteList(listName);

      if (!response.success) {
        throw new Error(response.message || 'Failed to delete list');
      }

      // Remove from local state
      lists.value = lists.value.filter((l) => l.name !== listName);

      return true;
    } catch (err: any) {
      error.value = err.message || 'Failed to delete list';
      console.error('Error deleting list:', err);
      return false;
    } finally {
      loading.value.saving = false;
    }
  }

  /**
   * Delete a value from a list
   * @param valueId - ID of the value to delete
   */
  async function deleteValue(valueId: string): Promise<boolean> {
    try {
      loading.value.saving = true;
      error.value = null;

      const response = await listOfValuesApiService.deleteValue({
        id: valueId,
      });

      if (!response.success) {
        throw new Error(response.message || 'Failed to delete value');
      }

      // Remove from local state
      currentValues.value = currentValues.value.filter((v) => v.id !== valueId);

      return true;
    } catch (err: any) {
      error.value = err.message || 'Failed to delete value';
      console.error('Error deleting value:', err);
      return false;
    } finally {
      loading.value.saving = false;
    }
  }

  /**
   * Fetch audit log for a value
   * TODO: Implement when backend endpoint is ready
   * @param valueId - Value identifier
   */
  async function fetchAuditLog(valueId: string): Promise<any[]> {
    try {
      // TODO: Implement when backend endpoint is ready
      // const response = await api.get(`/list-of-values/value/${valueId}/audit`);

      // Temporary mock data
      return [
        {
          id: 'audit_1',
          action: 'create',
          field_changed: null,
          old_value: null,
          new_value: 'Created value',
          changed_by: 'system',
          changed_by_name: 'System',
          changed_at: new Date().toISOString(),
        },
      ];
    } catch (err: any) {
      console.error('Error fetching audit log:', err);
      return [];
    }
  }

  return {
    // State
    lists,
    currentValues,
    loading,
    error,
    pagination,

    // Computed
    hasLists,
    hasValues,
    isLoading,

    // Methods
    fetchLists,
    fetchValuesForList,
    applySorting,
    saveCustomOrder,
    loadCustomOrder,
    deleteList,
    deleteValue,
    fetchAuditLog,
  };
}
