<template>
  <q-card>
    <q-toolbar class="text-white secondary-toolbar">
      <q-toolbar-title>{{ $t('create_new_list') }}</q-toolbar-title>
      <q-btn flat round dense icon="close" v-close-popup />
    </q-toolbar>
    <form
      @submit.prevent.stop="submitNewColumFrom"
      class="create-form q-pt-md q-pb-lg"
    >
      <q-card-section class="q-pt-none">
        <div class="row full-width mb-10 mt-8" style="margin-bottom: 20px">
          <div class="full-width">
            <q-input
              outlined
              dense
              :label="$t('Name')"
              v-model="model['name']"
              :class="
                'full-width' + (errors['name'] ? 'column-error-border' : '')
              "
            >
              <template v-slot:append>
                <q-icon
                  v-if="errors['name']"
                  flat
                  dense
                  name="error"
                  size="24px"
                  color="red"
                >
                  <q-tooltip class="bg-red line-error-tooltip">
                    <template v-if="errors['name'] == 'required'">
                      {{ $t('FIELD_REQUIRED') }}
                    </template>
                    <template
                      v-if="errors['name'] == 'only_characters_underscore'"
                    >
                      {{ $t('only_characters_underscore') }}
                    </template>

                    <template v-if="errors['name'] == 'duplicate_error'">
                      {{ $t('duplicate_error') }}
                    </template>
                  </q-tooltip>
                </q-icon>
              </template>
            </q-input>
          </div>
        </div>

        <div class="row full-width mb-10 mt-8" style="margin-bottom: 20px">
          <div class="full-width">
            <q-select
              outlined
              clearable
              v-model="model['sub_org_id']"
              use-input
              :options="filterSubOrgsList"
              @filter="filterSubOrgslistEvent"
              :label="$t('sub_organizations')"
              :loading="sub_org_list_loading"
              class="select-box"
              emit-value
              map-options
              popup-content-class="dropdown-fit"
            >
              <template v-slot:option="scope">
                <q-item v-bind="scope.itemProps">
                  <q-item-section>
                    <q-item-label>{{ scope.opt.label }}</q-item-label>
                    <q-tooltip>{{ scope.opt.label }}</q-tooltip>
                  </q-item-section>
                </q-item>
              </template>
            </q-select>
          </div>
        </div>
      </q-card-section>

      <q-card-actions align="right">
        <f-btn type="submit" class="q-mr-sm" :label="$t('save')" />
      </q-card-actions>

      <q-inner-loading :showing="loading">
        <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
      </q-inner-loading>
    </form>
  </q-card>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { useFieldValuesSettingsStore, useDropdownStore } from 'src/store/main';
import type { dynamicObj } from 'src/pages/assets';
import { onlyCharactersAndunderscore } from 'src/utils/general';
import { listOfValuesApiService } from 'src/services';
import { ApiExceptions } from 'src/exceptions/index';
export default defineComponent({
  props: {
    list_name: {
      type: String,
      default: '',
    },
  },
    components: {},
  data() {
    return {};
  },
  mounted: function () {
    this.init();
  },
  methods: {
    init() {
      try {
        this.list_names = Object.keys(this.list_of_values);
        this.resetModel();
      } catch (err: any) {
      } finally {
        // this.processing = false;
      }
    },

    resetModel() {
      this.model['name'] = '';
      this.resetErrors();
    },

    resetErrors() {
      for (const [name, index] of Object.entries(this.model)) {
        this.errors[name] = '';
      }
    },

    async submitNewColumFrom() {
      try {
        if (!this.validateRow()) {
          return;
        }
        this.loading = true;
        await this.saveNewRow();
        const event = new CustomEvent('row_added', {});
        document.dispatchEvent(event);

        notify.success('Record Created successfully');
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    async saveNewRow() {
      const data = {} as dynamicObj;
      data['name'] = this.model['name'];
      data['label'] = this.model['label'];
      if (this.model['sub_org_id']) {
        data['sub_org_id'] = this.model['sub_org_id'];
      }

      const response = await listOfValuesApiService.createList(data);
      if (response.success == false) {
        throw response.message;
      }
      this.resetModel();
    },

    validateRow() {
      let validate = true;
      this.resetErrors();

      if (!this.validateName()) {
        validate = false;
      }

      return validate;
    },

    validateName() {
      if (!this.model['name'] || this.model['name'].length == 0) {
        this.errors['name'] = 'required';
        return false;
      }

      if (!onlyCharactersAndunderscore(this.model['name'])) {
        this.errors['name'] = 'only_characters_underscore';
        return false;
      }

      if (this.list_names.includes(this.model['name'])) {
        this.errors['name'] = 'duplicate_error';
        return false;
      }
      return true;
    },

    filterSubOrgslistEvent(val: string, update: any, abort: any) {
      if (!val) {
        update(() => {
          this.filterSubOrgsList = this.subOrgList;
        });
        return;
      }

      update(() => {
        const needle = val.toLowerCase();
        this.filterSubOrgsList = this.subOrgList.filter(
          (v: any) => v.label.toLowerCase().indexOf(needle) > -1,
        );
      });
    },
  },

  setup() {
    const field_values_setting_store = useFieldValuesSettingsStore();
    const { list_of_values, processing } = storeToRefs(
      field_values_setting_store,
    );
    const { getLists } = field_values_setting_store;

    const dropdown_store = useDropdownStore();
    const filterSubOrgsList: any = ref(dropdown_store.subOrgList);
    const { subOrgList, sub_org_list_loading } = storeToRefs(dropdown_store);

    return {
      subOrgList,
      filterSubOrgsList,
      sub_org_list_loading,
      getLists,
      list_of_values,
      processing,
      model: ref({} as dynamicObj),
      errors: ref({} as dynamicObj),
      loading: ref(false),
      list_names: ref([] as string[]),
    };
  },
});
</script>
<style scoped>
.create-form {
  width: 500px;
  margin-left: auto;
  margin-right: auto;
}
.select-box {
  flex: 1;
}
.full-width {
  width: 100%;
}
</style>
