<template>
  <DocBitsTable
    :rows="values"
    :columns="columns"
    :loading="loading"
    row-key="id"
    table-id="lov_value_table"
    dense
    :features="{
      sorting: true,
      filtering: false,
      selection: true,
      bulkActions: true,
      rowActions: true,
      resizable: false,
      pagination: false,
      columnReorder: true,
      clientSideSort: true,
    }"
    :row-actions="rowActions"
    :pagination="sortState"
    :column-order="columnOrder"
    no-data-label="no_record_found"
    flat-style
    table-height="100%"
    @update:sorting="handleSort"
    @row-click="handleRowClick"
    @row-action="handleRowAction"
    @column-reorder="handleColumnReorder"
    @selection-change="handleSelectionChange"
  >
    <template #header-actions="{ selectedCount }">
      <q-btn
        v-if="selectedCount > 0"
        flat
        dense
        round
        icon="content_copy"
        color="primary"
        size="sm"
        class="q-ml-xs"
        @click="handleBulkDuplicate"
      >
        <q-tooltip>{{ $t('duplicate') }} ({{ selectedCount }})</q-tooltip>
      </q-btn>
    </template>

    <template #body-cell-sub_org="{ row }">
      <span v-if="getSubOrgName(row.sub_org_id)">{{ getSubOrgName(row.sub_org_id) }}</span>
      <span v-else class="text-grey-6">—</span>
    </template>

    <template #body-cell-synonyms="{ row }">
      <q-badge
        v-for="(synonym, idx) in row.synonyms"
        :key="idx"
        color="primary"
        class="q-mr-xs synonym-badge"
      >
        {{ synonym }}
      </q-badge>
      <span v-if="row.synonyms.length === 0" class="text-grey-6">—</span>
    </template>

    <template #body-cell-language="{ row }">
      <template v-for="(label, idx) in row.label" :key="idx">
        <q-badge v-if="label.language"
          class="q-mr-xs q-mb-xs label-badge language-badge"
          :style="{ backgroundColor: orgColor, color: 'white' }"
        >
          {{ getLanguageName(label.language) }}
        </q-badge>
        <span v-else class="text-grey-6">—</span>
      </template>
      <span v-if="!hasLabels(row)" class="text-grey-6">—</span>
    </template>

    <template #body-cell-label="{ row }">
      <template v-for="(label, idx) in row.label" :key="idx">
        <q-badge
          v-if="label.translated_value"
          class="q-mr-xs q-mb-xs label-badge"
          :style="{ backgroundColor: orgColor, color: 'white' }"
        >
          {{ label.translated_value }}
        </q-badge>
      </template>
      <span v-if="!hasLabels(row)" class="text-grey-6">—</span>
    </template>
  </DocBitsTable>
</template>

<script lang="ts">

import cache from 'src/utils/cache';
import { storeToRefs } from 'pinia';
import type { ListValue } from '../types';
import { defineComponent, type PropType } from 'vue';
import { CONSTANTS, DEFAULT_ORG_UUID } from 'src/constants';
import DocBitsTable from 'src/components/Table/DocBitsTable.vue';
import { useDropdownStore, useSettingStore } from 'src/store/main';
import type { UnifiedTableColumn, RowActionItem } from 'src/components/Table/types/table/unified-table';

export default defineComponent({
  name: 'ValueTable',
  mixins: [cache],
  components: { DocBitsTable },

  props: {
    values: {
      type: Array as PropType<ListValue[]>,
      required: true,
    },
    selectedRowId: {
      type: String as PropType<string | null>,
      default: null,
    },
    loading: {
      type: Boolean,
      default: false,
    },
  },

  emits: ['row-clicked', 'edit', 'delete', 'duplicate'],

  setup() {
    const setting_store = useSettingStore();
    const { user_settings } = storeToRefs(setting_store);
    const dropdown_store = useDropdownStore();
    const { languages_list, subOrgList } = storeToRefs(dropdown_store);
    const { getLanguageList, getSubOrgsList, getSubOrgName } = dropdown_store;
    return { user_settings, languages_list, getLanguageList, subOrgList, getSubOrgsList, getSubOrgName };
  },

  data() {
    return {
      sortState: {
        sortBy: '' as string,
        descending: false,
      },
      columnOrder: [] as string[],
      selectedRows: [] as ListValue[],
    };
  },

  mounted() {
    if (!this.languages_list || this.languages_list.length === 0) {
      this.getLanguageList();
    }
    if (!this.subOrgList || this.subOrgList.length === 0) {
      this.getSubOrgsList();
    }
    const saved = this.getDataByKey(CONSTANTS.lov_value_columns_order);
    if (typeof saved === 'string') {
      try {
        const parsed = JSON.parse(saved);
        if (Array.isArray(parsed)) {
          this.columnOrder = parsed;
        }
      } catch {
        // ignore malformed value
      }
    }
  },

  computed: {
    columns(): UnifiedTableColumn[] {
      return [
        {
          name: 'value',
          label: this.$t('value'),
          field: 'value',
          align: 'left' as const,
          sortable: true,
        },
        {
          name: 'sub_org',
          label: this.$t('sub_organization'),
          field: 'sub_org_id',
          align: 'left' as const,
          sortable: true,
        },
        {
          name: 'synonyms',
          label: this.$t('synonyms'),
          field: 'synonyms',
          align: 'left' as const,
          sortable: true,
        },
        {
          name: 'language',
          label: this.$t('language'),
          field: 'label',
          align: 'left' as const,
          sortable: false,
        },
        {
          name: 'label',
          label: this.$t('label'),
          field: 'label',
          align: 'left' as const,
          sortable: false,
          width: '320px',
          style: 'min-width: 320px;',
          headerStyle: 'min-width: 320px;',
        },
      ];
    },

    orgColor(): string {
      return (this.user_settings?.['ORG_COLOR_PREFERENCE'] as string) || '#1976d2';
    },

    rowActions(): RowActionItem[] {
      return [
        {
          key: 'edit',
          label: this.$t('edit'),
          icon: 'edit',
        },
        {
          key: 'duplicate',
          label: this.$t('duplicate'),
          icon: 'content_copy',
        },
        {
          key: 'delete',
          label: this.$t('delete'),
          icon: 'delete',
          color: 'negative',
          separator: true,
          show: (row: ListValue) => row.org_id !== DEFAULT_ORG_UUID,
        },
      ];
    },
  },

  methods: {
    handleRowClick(payload: { row: ListValue; rowIndex: number }) {
      this.$emit('row-clicked', payload.row);
    },

    handleRowAction(payload: { action: string; rowId: string; row: ListValue }) {
      if (payload.action === 'edit') {
        this.$emit('edit', payload.row);
      } else if (payload.action === 'duplicate') {
        this.$emit('duplicate', [payload.row]);
      } else if (payload.action === 'delete') {
        this.$emit('delete', payload.row);
      }
    },

    handleSelectionChange(payload: { selectedRows: ListValue[] }) {
      this.selectedRows = payload.selectedRows;
    },

    handleBulkDuplicate() {
      if (this.selectedRows.length === 0) return;
      this.$emit('duplicate', this.selectedRows);
    },

    handleSort(payload: { column: string; direction: string }) {
      this.sortState.sortBy = payload.column;
      this.sortState.descending = payload.direction === 'desc';
    },

    handleColumnReorder(newOrder: string[]) {
      this.columnOrder = newOrder;
      this.setDataToLocalStorage(CONSTANTS.lov_value_columns_order, JSON.stringify(newOrder));
    },

    hasLabels(row: ListValue): boolean {
      return Array.isArray(row.label) && row.label.some((l) => !!l.translated_value);
    },

    getLanguageName(code: string): string {
      if (!code) return '';
      const normalized = code.toLowerCase();
      const match = (this.languages_list || []).find(
        (lang: any) => String(lang.value).toLowerCase() === normalized,
      );
      return match?.label || code;
    },
  },
});
</script>

<style scoped lang="scss">
.synonym-badge {
  font-size: 0.75rem;
  padding: 2px 8px;
}

:deep(.label-badge) {
  font-size: 0.75rem !important;
  padding: 2px 9px !important;
  font-weight: 500 !important;
  border-radius: 999px !important;
  line-height: 1.3 !important;
  white-space: normal !important;
}

:deep(.language-badge) {
  text-transform: capitalize;
}

:deep(#lov_value_table tbody tr.data-row) {
  cursor: pointer;
}
</style>
