<template>
  <div class="lov-redesign">
    <div class="lov-panels">
      <div class="lov-sidebar">
        <ListNavigator
          :lists="lists"
          :selectedListId="selectedListId"
          @list-selected="handleListSelected"
        />
      </div>
      <div class="lov-main">
        <div v-if="selectedListId" class="lov-content">
          <!-- Toolbar row -->
          <div class="lov-toolbar row items-center q-mb-sm">
            <SortControls
              :currentSort="currentSort"
              @sort-changed="handleSortChanged"
            />
            <q-space />
            <q-btn
              color="primary"
              icon="add"
              :label="$t('add_row')"
              dense
              unelevated
              no-caps
              @click="handleAddNewItem"
            />
          </div>
          <!-- Single splitter: table top / form bottom -->
          <q-splitter
            v-model="activeSplitter"
            horizontal
            :limits="formVisible ? [20, 80] : [100, 100]"
            :disable="!formVisible"
            class="lov-splitter"
            :separator-class="formVisible ? 'lov-separator' : 'lov-separator-hidden'"
          >
            <template v-slot:before>
              <ValueTable
                :key="valueTableKey"
                :values="currentValues"
                :selectedRowId="selectedValue?.id || null"
                :loading="loading.values"
                @row-clicked="handleRowClicked"
                @edit="handleRowClicked"
                @duplicate="handleDuplicate"
                @delete="handleDelete"
              />
              <Loader />
            </template>
            <template v-slot:after>
              <div v-if="formVisible" class="lov-form-panel" :key="isNewItem ? 'new' : selectedValue?.id">
                <ValueEditForm
                  :value="selectedValue"
                  :visible="formVisible"
                  :isNew="isNewItem"
                  :listName="selectedListId"
                  :selectedListOrgId="selectedListOrgId"
                  @save="handleSave"
                  @cancel="handleCancel"
                />
              </div>
            </template>
          </q-splitter>
        </div>
        <div v-else class="empty-state">
          <p>{{ $t('select_list_to_view_values') }}</p>
        </div>
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { isDefaultOrg } from 'src/constants';
import Loader from 'src/components/Loader.vue';
import helperMixin from 'src/mixins/helperMixin';
import ValueTable from './components/ValueTable.vue';
import SortControls from './components/SortControls.vue';
import ListNavigator from './components/ListNavigator.vue';
import ValueEditForm from './components/ValueEditForm.vue';
import { useListOfValues } from './composables/useListOfValues';
import type { ListValue, SortPreference, ValueFormData } from './types';
import { notify } from 'src/components/notifications/notify';
import { listOfValuesApiService } from 'src/services';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets';

export default defineComponent({
  name: 'ListOfValues',

  mixins: [helperMixin],

  components: {
    ListNavigator,
    SortControls,
    ValueTable,
    ValueEditForm,
    Loader,
  },

  setup() {
    const {
      lists,
      currentValues,
      loading,
      fetchLists,
      fetchValuesForList,
      applySorting,
      deleteValue,
    } = useListOfValues();

    return {
      lists,
      currentValues,
      loading,
      fetchLists,
      fetchValuesForList,
      applySorting,
      deleteValue,
    };
  },

  data() {
    return {
      selectedListId: null as string | null,
      selectedValue: null as ListValue | null,
      formVisible: false,
      isNewItem: false,
      currentSort: 'alphabetical' as SortPreference,
      splitterPosition: 50,
      valueTableKey: 0,
    };
  },

  computed: {
    activeSplitter: {
      get(): number {
        return this.formVisible ? this.splitterPosition : 100;
      },
      set(val: number) {
        if (this.formVisible) {
          this.splitterPosition = val;
        }
      },
    },
    selectedListOrgId(): string {
      const list = this.lists.find((l) => l.id === this.selectedListId);
      return list?.org_id || '';
    },
  },

  mounted() {
    this.fetchLists();
  },

  methods: {
    async handleListSelected(listId: string) {
      this.selectedListId = listId;
      this.selectedValue = null;
      this.formVisible = false;
      this.isNewItem = false;
      this.currentValues = [];
      await this.fetchValuesForList(listId, this.currentSort);
    },

    handleSortChanged(newSort: SortPreference) {
      this.currentSort = newSort;
      this.currentValues = this.applySorting(this.currentValues, newSort);
    },

    handleAddNewItem() {
      this.selectedValue = null;
      this.isNewItem = true;
      this.formVisible = true;
    },

    handleRowClicked(value: ListValue) {
      if (this.selectedValue?.id === value.id) {
        this.formVisible = !this.formVisible;
      } else {
        this.selectedValue = value;
        this.isNewItem = false;
        this.formVisible = true;
      }
    },

    prepareApiData(formData: ValueFormData, isEdit: boolean): dynamicObj {
      const data = {} as dynamicObj;
      data['name'] = this.selectedListId;
      data['value'] = formData.value;
      data['sub_org_id'] = formData.sub_org_id || null;
      data['synonyms'] =
        formData.synonyms.length > 0
          ? JSON.stringify(formData.synonyms)
          : '[]';
      data['org_id'] = this.selectedListOrgId;

      // For DEFAULT org lists, skip the DEFAULT inherited translation
      // For all lists, skip translations with empty labels
      let labelsToSend = [...formData.labels];
      if (isDefaultOrg(this.selectedListOrgId)) {
        // Remove the first DEFAULT inherited translation (same as old shift() logic)
        const defaultIdx = labelsToSend.findIndex(
          (l) => isDefaultOrg(l.org_id),
        );
        if (defaultIdx !== -1) {
          labelsToSend.splice(defaultIdx, 1);
        }
      }

      const translations = labelsToSend
        .filter(
          (label) =>
            label.translated_value &&
            label.translated_value.trim() !== '' &&
            !isDefaultOrg(label.org_id),
        )
        .map((label, index) => ({
          language_code: label.language,
          label: label.translated_value,
          org_id: label.org_id || this.selectedListOrgId,
          is_default: index === 0,
        }));

      data['translations'] = translations;

      data['label'] = formData.value || (this.selectedValue?.value ?? null);

      return data;
    },

    async handleSave(formData: ValueFormData) {
      if (!this.selectedListId) return;

      if (!formData.value || formData.value.trim() === '') {
        notify.error(this.$t('empty_not_valid'));
        return;
      }

      try {
        let response: dynamicObj;
        const isEdit = !this.isNewItem && !!this.selectedValue;
        const data = this.prepareApiData(formData, isEdit);

        if (data['translations'].length === 0 && this.isNewItem) {
          notify.error(this.$t('required_atleast_one_row'));
          return;
        }

        if (this.isNewItem) {
          response = await listOfValuesApiService.createValuesForlist(data);
        } else if (this.selectedValue) {
          data['id'] = this.selectedValue.id;
          response = await listOfValuesApiService.editValueForlist(data);
        } else {
          return;
        }

        if (response.success === true) {
          notify.success(this.$t('MSG_SAVE'));

          if (!this.isNewItem && this.selectedValue) {
            const idx = this.currentValues.findIndex(
              (v: ListValue) => v.id === this.selectedValue!.id,
            );
            if (idx !== -1) {
              this.currentValues[idx] = {
                ...this.currentValues[idx],
                value: formData.value,
                sub_org_id: formData.sub_org_id,
                synonyms: [...formData.synonyms],
                label: formData.labels.map((l) => ({ ...l })),
                updated_at: new Date().toISOString(),
              };
              this.currentValues = this.applySorting(
                this.currentValues,
                this.currentSort,
              );
              this.valueTableKey++;
            }
            this.formVisible = false;
            this.selectedValue = null;
            this.isNewItem = false;
          } else {
            this.formVisible = false;
            this.selectedValue = null;
            this.isNewItem = false;
            await this.fetchValuesForList(this.selectedListId, this.currentSort);
          }
        } else {
          const error_message = ApiExceptions.getErrorMessage(response[0]);
          notify.error(error_message);
        }
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
      }
    },

    handleCancel() {
      this.formVisible = false;
      this.selectedValue = null;
      this.isNewItem = false;
    },

    async handleDuplicate(rows: ListValue[]) {
      if (!this.selectedListId || rows.length === 0) return;

      this.showLoading();
      try {
        const response = await listOfValuesApiService.duplicateValues({
          ids: rows.map((r) => r.id).join(','),
        });

        if (response.success === true) {
          notify.success(this.$t('MSG_SAVE'));
          await this.fetchValuesForList(this.selectedListId, this.currentSort);
        }
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
      } finally {
        this.hideLoading();
      }
    },

    async handleDelete(value: ListValue) {
      if (!this.selectedListId) return;

      this.showLoading();
      try {
        const success = await this.deleteValue(value.id);
        if (success) {
          notify.success(this.$t('MSG_DELETE'));
          this.formVisible = false;
          this.selectedValue = null;
        }
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
      } finally {
        this.hideLoading();
      }
    },

  },
});
</script>

